import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.B3-dzFNu.js";const u=JSON.parse('{"title":"Redline","description":"Review Git changes locally or in GitHub Actions with Pi or OpenCode.","frontmatter":{"layout":"home","title":"Redline","description":"Review Git changes locally or in GitHub Actions with Pi or OpenCode.","hero":{"name":"Redline","text":"Review Git changes with Pi or OpenCode","tagline":"Run a local review or review pull requests in GitHub Actions. Read the findings and keep the JSON and Markdown results.","actions":[{"theme":"brand","text":"Get started","link":"/get-started/"},{"theme":"alt","text":"Find a command","link":"/commands"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1793498569000}'),s={name:"index.md"};function d(o,e,n,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="what-do-you-want-to-do" tabindex="-1">What do you want to do? <a class="header-anchor" href="#what-do-you-want-to-do" aria-label="Permalink to &quot;What do you want to do?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Start here</th></tr></thead><tbody><tr><td>Install Redline or try the source checkout</td><td><a href="/projects/redline/get-started/">Get started</a></td></tr><tr><td>Check the workflow without an API key</td><td><a href="/projects/redline/get-started/first-review">Run your first review</a></td></tr><tr><td>Review with a real model</td><td><a href="/projects/redline/get-started/configuration">Connect a model</a></td></tr><tr><td>Review staged changes, a branch, or two commits</td><td><a href="/projects/redline/commands">Common commands</a></td></tr><tr><td>Understand findings, coverage, and output files</td><td><a href="/projects/redline/results">Read the results</a></td></tr><tr><td>Review GitHub pull requests</td><td><a href="/projects/redline/get-started/github-actions">Set up GitHub Actions</a></td></tr><tr><td>Fix a setup or review failure</td><td><a href="/projects/redline/troubleshooting">Troubleshooting</a></td></tr></tbody></table><h2 id="the-shortest-safe-trial" tabindex="-1">The shortest safe trial <a class="header-anchor" href="#the-shortest-safe-trial" aria-label="Permalink to &quot;The shortest safe trial&quot;">​</a></h2><p>From a Git repository with a committed <code>HEAD</code> and tracked changes:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --indexing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disabled</span></span></code></pre></div><p><code>echo</code> checks the review workflow without a model, API key, or indexer. It always produces a clean answer, so it does not tell you whether the code has defects. The <a href="/projects/redline/get-started/first-review">first-review guide</a> includes a disposable example and the source-checkout command.</p><h2 id="what-redline-does" tabindex="-1">What Redline does <a class="header-anchor" href="#what-redline-does" aria-label="Permalink to &quot;What Redline does&quot;">​</a></h2><p>Redline captures the selected Git change, reviews eligible files, validates the structure and diff evidence of findings, and writes review artifacts. It does not apply fixes or execute the reviewed repository&#39;s code, tests, or installers. Model findings still need human review.</p><p>GitHub Actions can also publish validated findings and a managed summary when publication credentials are configured. Other forges, editor integrations, a container sandbox, and managed local model runtimes are not implemented. See the <a href="/projects/redline/portable-architecture">architecture reference</a> for those boundaries.</p>',9)])])}const f=t(s,[["render",d]]);export{u as __pageData,f as default};
